SCHEMA='''
CREATE TABLE IF NOT EXISTS app_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'readonly',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,scope TEXT NOT NULL DEFAULT 'Yurt İçi',country TEXT NOT NULL DEFAULT 'Türkiye',city TEXT,district TEXT,address TEXT,description TEXT,manager TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS systems(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,system_type TEXT,status TEXT NOT NULL DEFAULT 'Aktif',quantity REAL NOT NULL DEFAULT 0,unit TEXT NOT NULL DEFAULT 'Adet',installation_year INTEGER,installation_date TEXT,latitude REAL,longitude REAL,city TEXT,district TEXT,address TEXT,description TEXT,cost REAL NOT NULL DEFAULT 0,currency TEXT NOT NULL DEFAULT 'TRY',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(project_id,name));
CREATE TABLE IF NOT EXISTS faults(id INTEGER PRIMARY KEY AUTOINCREMENT,system_id INTEGER NOT NULL REFERENCES systems(id) ON DELETE CASCADE,fault_date TEXT NOT NULL,fault_type TEXT,description TEXT NOT NULL,action_taken TEXT,replaced_part TEXT,result TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,system_id INTEGER REFERENCES systems(id) ON DELETE CASCADE,filename TEXT NOT NULL,original_name TEXT NOT NULL,mime_type TEXT NOT NULL,size INTEGER NOT NULL,uploaded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS photos(id INTEGER PRIMARY KEY AUTOINCREMENT,system_id INTEGER NOT NULL REFERENCES systems(id) ON DELETE CASCADE,filename TEXT NOT NULL,original_name TEXT NOT NULL,mime_type TEXT NOT NULL,size INTEGER NOT NULL,uploaded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,action TEXT NOT NULL,entity TEXT,entity_id INTEGER,details TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS status_history(id INTEGER PRIMARY KEY AUTOINCREMENT,system_id INTEGER NOT NULL REFERENCES systems(id) ON DELETE CASCADE,status TEXT NOT NULL,reason TEXT NOT NULL,changed_at TEXT NOT NULL,changed_by TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_status_history_system ON status_history(system_id);
CREATE INDEX IF NOT EXISTS idx_status_history_date ON status_history(changed_at);
CREATE INDEX IF NOT EXISTS idx_systems_project ON systems(project_id);CREATE INDEX IF NOT EXISTS idx_systems_status ON systems(status);CREATE INDEX IF NOT EXISTS idx_faults_system ON faults(system_id);CREATE INDEX IF NOT EXISTS idx_docs_project ON documents(project_id);
'''

def now(): return datetime.now().strftime('%Y-%m-%d %H:%M:%S')
def db():
 c=sqlite3.connect(DB_PATH); c.row_factory=sqlite3.Row; c.execute('PRAGMA foreign_keys=ON'); return c
def h(x): return html.escape('' if x is None else str(x),quote=True)
def hashpw(p,s=None):
 s=s or secrets.token_bytes(16); d=p.encode()+s
 for _ in range(40000): d=hashlib.sha256(d).digest()
 return s.hex()+'$'+d.hex()
def verifypw(p,stored):
 try:
  s,d=stored.split('$',1); x=p.encode()+bytes.fromhex(s)
  for _ in range(40000): x=hashlib.sha256(x).digest()
  return secrets.compare_digest(x.hex(),d)
 except: return False

def init():
 c=db(); c.executescript(SCHEMA)
 c.execute("INSERT OR IGNORE INTO schema_version(version) VALUES(1)")
 if not c.execute('SELECT 1 FROM users LIMIT 1').fetchone():
  t=now(); c.execute('INSERT INTO users(username,password_hash,role,created_at,updated_at) VALUES(?,?,?,?,?)',(DEFAULT_ADMIN_USERNAME,hashpw(DEFAULT_ADMIN_PASSWORD),'admin',t,t)); c.execute('INSERT INTO users(username,password_hash,role,created_at,updated_at) VALUES(?,?,?,?,?)',(DEFAULT_VIEWER_USERNAME,hashpw(DEFAULT_VIEWER_PASSWORD),'readonly',t,t))
