def system_form(project_id,s=None,user=None):
 s=s or {}; st=s.get('status','Aktif')
 body=f"""<h1>{'Sistem Düzenle' if s else 'Sistem Ekle'}</h1><div class="card"><div class="notice">Durum değişikliği ayrı bir geçmiş kaydı oluşturur. <b>Pasif</b> için pasif olma nedeni, <b>Arızalı</b> için arıza açıklaması zorunludur.</div><form method="post" action="/system/save" class="formgrid" onsubmit="return validateStatusForm()"><input type="hidden" name="id" value="{s.get('id','')}"><input type="hidden" name="project_id" value="{project_id}"><div><label>Sistem Adı *</label><input name="name" value="{h(s.get('name',''))}" required></div><div><label>Sistem Türü</label><input name="system_type" value="{h(s.get('system_type',''))}"></div><div><label>Durum *</label><select id="status" name="status" onchange="toggleStatusReason()"><option {'selected' if st=='Aktif' else ''}>Aktif</option><option {'selected' if st=='Pasif' else ''}>Pasif</option><option {'selected' if st=='Arızalı' else ''}>Arızalı</option></select></div><div id="statusReasonBox" class="full"><label id="statusReasonLabel">Durum açıklaması *</label><textarea id="statusReason" name="status_reason" placeholder="Durum değişikliğinin gerekçesini yazın...">{h(s.get('status_reason',''))}</textarea></div><div><label>Miktar</label><input type="number" step="any" name="quantity" value="{h(s.get('quantity',0))}"></div><div><label>Birim</label><input name="unit" value="{h(s.get('unit','Adet'))}"></div><div><label>Kurulum Yılı</label><input name="installation_year" value="{h(s.get('installation_year',''))}"></div><div><label>İl</label><input name="city" value="{h(s.get('city',''))}"></div><div><label>İlçe</label><input name="district" value="{h(s.get('district',''))}"></div><div class="full"><label>Adres</label><input name="address" value="{h(s.get('address',''))}"></div><div><label>Enlem</label><input id="lat" name="latitude" value="{h(s.get('latitude',''))}"></div><div><label>Boylam</label><input id="lon" name="longitude" value="{h(s.get('longitude',''))}"></div><div><label>Maliyet</label><input type="number" step="any" name="cost" value="{h(s.get('cost',0))}"></div><div><label>Para Birimi</label><input name="currency" value="{h(s.get('currency','TRY'))}"></div><div class="full"><button type="button" class="btn secondary" onclick="openPicker()">📍 Haritadan Konum Seç</button> <span class="muted">Tıklanan noktanın koordinatı doğrudan alınır.</span></div><div class="full"><label>Kurulum Tarihi</label><input type="date" name="installation_date" value="{h(s.get('installation_date',''))}"></div><div class="full"><label>Açıklama</label><textarea name="description">{h(s.get('description',''))}</textarea></div><div class="actions full"><button class="btn green">Kaydet</button><a class="btn secondary" href="/project/{project_id}">Vazgeç</a></div></form></div><div id="picker" class="picker" style="display:none"><div class="pickerbox"><h2>Konum Seç</h2><p class="muted">Dünya haritasında tam konuma tıklayın.</p><div id="pickmap" class="pickmap" onclick="pickPoint(event)"><div id="pickcross" class="pickcross"></div></div><div class="actions"><button type="button" class="btn green" onclick="usePicked()">Bu Konumu Kullan</button><button type="button" class="btn secondary" onclick="closePicker()">İptal</button></div></div></div><script>function toggleStatusReason(){{const st=document.getElementById('status').value,b=document.getElementById('statusReasonBox'),r=document.getElementById('statusReason'),l=document.getElementById('statusReasonLabel');b.style.display=st==='Aktif'?'none':'block';r.required=st!=='Aktif';l.textContent=st==='Pasif'?'Pasif olma nedeni *':'Arıza açıklaması *'}}function validateStatusForm(){{const st=document.getElementById('status').value,r=document.getElementById('statusReason');if(st!=='Aktif'&&!r.value.trim()){{alert(st==='Pasif'?'Pasif olma nedeni zorunludur.':'Arıza açıklaması zorunludur.');r.focus();return false}}return true}}let picked=null;function openPicker(){{document.getElementById('picker').style.display='flex';picked=null}}function closePicker(){{document.getElementById('picker').style.display='none'}}function pickPoint(e){{const m=e.currentTarget,rect=m.getBoundingClientRect(),x=Math.max(0,Math.min(rect.width,e.clientX-rect.left)),y=Math.max(0,Math.min(rect.height,e.clientY-rect.top));picked={{lat:90-y/rect.height*180,lon:x/rect.width*360-180}};const c=document.getElementById('pickcross');c.style.display='block';c.style.left=x+'px';c.style.top=y+'px'}}function usePicked(){{if(!picked){{alert('Haritada bir nokta seçin.');return}}document.getElementById('lat').value=picked.lat.toFixed(6);document.getElementById('lon').value=picked.lon.toFixed(6);closePicker()}}toggleStatusReason();</script>"""
 return page('Sistem',body,user)

def mapbox(systems):
 mtype=setting('map_type','XYZ').upper();url=setting('map_url','').strip();layer=setting('map_layer','').strip();fmt=setting('map_format','image/png').strip() or 'image/png';ver=setting('map_version','1.3.0').strip() or '1.3.0'
 try:zoom=int(setting('map_zoom','6'))
 except:zoom=6
 try:lat=float(setting('map_center_lat','39'));lon=float(setting('map_center_lon','35'))
 except:lat,lon=39,35
 markers=[{'id':x['id'],'name':x['name'],'status':x['status'],'lat':float(x['latitude']),'lon':float(x['longitude']),'cls':status_class(x['status'])} for x in systems if x['latitude'] is not None and x['longitude'] is not None]
 cfg={'type':mtype,'url':url,'layer':layer,'format':fmt,'version':ver,'zoom':zoom,'lat':lat,'lon':lon,'markers':markers,'fallback':'/static/maps/world.png'};cfgjson=json.dumps(cfg,ensure_ascii=False).replace('</','<\\/')
 mid=id(systems)
 return f'''<div class="mapbox modern-map"><div id="map-{mid}" class="mapcanvas"></div><div class="maptools"><button type="button" onclick="mapZoom(1)">＋</button><button type="button" onclick="mapZoom(-1)">−</button><button type="button" onclick="mapReset()">⌖</button></div><div class="mapnote">{h(setting('map_name','Yerel Harita Sunucusu'))} · {h(mtype if url else 'Offline Yerel Harita')}</div><div class="maplegend"><span><i class="lg active"></i>Aktif</span><span><i class="lg passive"></i>Pasif</span><span><i class="lg fault"></i>Arızalı</span></div><div id="mapmsg-{mid}" class="mapmsg">Harita yükleniyor…</div><script>window.addEventListener('load',function(){{const cfg={cfgjson},root=document.getElementById('map-{mid}'),msg=document.getElementById('mapmsg-{mid}');window._pysMap={{cfg,root,msg,zoom:cfg.zoom}};PYSMap.init(window._pysMap);}});</script></div>'''

def dashboard(qs,user):
 project=qs.get('project',[''])[0];system=qs.get('system',[''])[0];status=qs.get('status',[''])[0];c=db();projects=c.execute('SELECT * FROM projects ORDER BY name').fetchall();where=[];args=[]
 if project.isdigit():where.append('s.project_id=?');args.append(int(project))
 if system and project.isdigit():where.append('s.name=?');args.append(system)
 if status:where.append('s.status=?');args.append(status)
 ww=' WHERE '+' AND '.join(where) if where else '';systems=c.execute('SELECT s.*,p.name project_name FROM systems s JOIN projects p ON p.id=s.project_id'+ww+' ORDER BY p.name,s.name',args).fetchall();allsys=c.execute('SELECT s.name,s.project_id,p.name project_name FROM systems s JOIN projects p ON p.id=s.project_id ORDER BY p.name,s.name').fetchall();ops=c.execute('SELECT * FROM audit_log ORDER BY id DESC LIMIT 10').fetchall();c.close()
 total=len(systems);k={st:sum(1 for x in systems if x['status']==st) for st in ('Aktif','Pasif','Arızalı')};opts=''.join(f'<option value="{p["id"]}" {"selected" if project==str(p["id"]) else ""}>{h(p["name"])}</option>' for p in projects);sysopts=''.join(f'<option value="{h(x["name"])}" data-project="{x["project_id"]}">{h(x["name"])}</option>' for x in allsys);rows=''.join(f'<tr><td><a href="/project/{x["project_id"]}">{h(x["project_name"])}</a></td><td><a href="/system/{x["id"]}">{h(x["name"])}</a></td><td>{h(x["system_type"] or "-")}</td><td><span class="pill {status_class(x["status"])}">{h(x["status"])}</span></td><td>{h(x["city"] or "-")}</td></tr>' for x in systems);mx=max(1,total);bars=''.join(f'<div class="barrow"><span>{st}</span><span class="bar"><i style="width:{k[st]/mx*100:.1f}%"></i></span><span class="metric">{k[st]}</span></div>' for st in ('Aktif','Pasif','Arızalı'));oprows=''.join(f'<div class="timelineitem"><div><b>{h(o["action"])}</b> · {h(o["entity"] or "")}</div><div class="small">{h(o["details"] or "")}</div><div class="time">{h(o["created_at"])}</div></div>' for o in ops)
 js='''<script>const p=document.getElementById("project"),s=document.getElementById("system");const all=[...s.options].slice(1);function sync(){const id=p.value,cur=s.value;s.innerHTML='<option value="">'+(id?'Tüm sistemler':'Önce proje seçin')+'</option>';all.forEach(o=>{if(id&&o.dataset.project===id)s.appendChild(o.cloneNode(true))});if([...s.options].some(o=>o.value===cur))s.value=cur;if(!id)s.value=''}sync();p.addEventListener('change',()=>{s.value='';sync()});</script>'''
 return page('Dashboard',f'''<section class="hero"><h1>Proje Yönetim Dashboard</h1><div>Proje → sistem yapısı, güncel durumlar ve geçmiş operasyonlar tek ekranda.</div></section><div class="grid"><div class="card"><div class="kpiicon">📁</div><div class="stat">{len(projects)}</div><div class="muted">Toplam Proje</div></div><div class="card"><div class="kpiicon">🖥️</div><div class="stat">{total}</div><div class="muted">Filtrelenen Sistem</div></div><div class="card"><div class="kpiicon">🟢</div><div class="stat">{k['Aktif']}</div><div class="muted">Aktif</div></div><div class="card"><div class="kpiicon">🔴</div><div class="stat">{k['Arızalı']}</div><div class="muted">Arızalı</div></div></div><div class="card"><h2>Filtreler</h2><form class="toolbar" method="get"><div><label>Proje</label><select id="project" name="project"><option value="">Tüm projeler</option>{opts}</select></div><div><label>Sistem</label><select id="system" name="system"><option value="">Önce proje seçin</option>{sysopts}</select></div><div><label>Durum</label><select name="status"><option value="">Tüm durumlar</option><option {'selected' if status=='Aktif' else ''}>Aktif</option><option {'selected' if status=='Pasif' else ''}>Pasif</option><option {'selected' if status=='Arızalı' else ''}>Arızalı</option></select></div><div><button class="btn">Filtrele</button></div></form></div><div class="two"><div class="card"><h2>Durum Özeti</h2>{bars}<p class="muted">Grafik seçilen proje/sistem/durum kapsamına göre güncellenir.</p></div><div class="card"><h2>Son İşlemler</h2><div class="timeline">{oprows or '<p class="muted">Henüz işlem yok.</p>'}</div></div></div><div class="card"><h2>Harita</h2>{mapbox(systems)}</div><div class="card"><h2>Filtrelenen Sistemler</h2><table><tr><th>Proje</th><th>Sistem</th><th>Tür</th><th>Durum</th><th>Konum</th></tr>{rows or '<tr><td colspan="5">Kayıt bulunamadı.</td></tr>'}</table></div>{js}''',user)

