class H(BaseHTTPRequestHandler):
 def out(self,data,code=200,ctype='text/html; charset=utf-8',cookies=None):
  b=data.encode() if isinstance(data,str) else data;self.send_response(code);self.send_header('Content-Type',ctype);self.send_header('Content-Length',str(len(b)));self.send_header('Cache-Control','no-store')
  for x in cookies or []:self.send_header('Set-Cookie',x)
  self.end_headers();self.wfile.write(b)
 def redir(self,u,cookies=None):self.send_response(303);self.send_header('Location',u);[self.send_header('Set-Cookie',x) for x in cookies or []];self.end_headers()
 def body(self):
  n=int(self.headers.get('Content-Length','0'))
  if n>MAX_UPLOAD+2_000_000:raise ValueError('İstek çok büyük.')
  return self.rfile.read(n)
