    c=db();d=c.execute('SELECT * FROM documents WHERE id=?',(int(m.group(1)),)).fetchone();c.close()
    if not d:return self.out('Bulunamadı',404)
    fp=os.path.join(UPLOAD_DIR,d['filename']);data=open(fp,'rb').read();self.send_response(200);self.send_header('Content-Type',d['mime_type'] or 'application/octet-stream');self.send_header('Content-Disposition',f'attachment; filename="{d["original_name"].replace(chr(34),"")}"');self.send_header('Content-Length',str(len(data)));self.end_headers();return self.wfile.write(data)
